package io.knowledgebrain.activity;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
import io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1;import io.knowledgebrain.contracts.content.metadata.v1.*;
class MetadataActivityTest extends ActivityFixtures {
 static final String TOPIC="content.note-metadata.v1";
 MetadataPropertyV1 property(String type,String raw){return MetadataPropertyV1.newBuilder().setPropertyId(id().toString()).setName(type).setValueType(type).setJsonValue(raw).build();}
 @Test void independentVersionsAndOriginalNamesIdsTypedValuesRemainImmutable()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("NOTE_METADATA",id()));var p=NoteMetadataChangedPayloadV1.parseFrom(env.getPayload());var tag=MetadataTagV1.newBuilder().setTagId(id().toString()).setName("Study 한글").build();var fields=List.of(property("STRING","\"<script>text</script>\\n\""),property("NUMBER","12345678901234567890.123456789012345678"),property("BOOLEAN","true"),property("DATE","\"0000-02-29\""),property("STRING_LIST","[\"first\\nsecond\",\"\"]"));var raw=env.toBuilder().setPayload(p.toBuilder().setMetadataVersion(24).setNoteVersion(7).addTags(tag).addAllProperties(fields).build().toByteString()).build().toByteArray();var e=ActivityEvent.decode(TOPIC,raw);assertEquals(24,e.sourceVersion());assertEquals(7,e.metadata().noteVersion());assertEquals(p.getRevisionId(),e.metadata().revisionId().toString());assertEquals(tag.getName(),e.metadata().tags().getFirst().name());assertEquals(fields.stream().map(MetadataPropertyV1::getJsonValue).toList(),e.metadata().properties().stream().map(ActivityEvent.Property::jsonValue).toList());assertTrue(ActivityEvent.target(e));assertEquals("/api/spaces/"+e.spaceId()+"/notes/"+e.aggregateId()+"/metadata",e.targetPath());assertNull(e.note());assertNull(e.noteConcepts());ActivityEvent.transport(TOPIC,raw,e.aggregateId().toString(),headers(e));}
 @Test void canonicalExpandedNegativeScaleNumbersDoNotNarrowTheFrozenInputContract(){for(String raw:List.of("12345678901234567890123456789012345678"+"0".repeat(18),"1"+"0".repeat(55),"0.000000000000000001","1E-18","-0.000","1.2300"))assertDoesNotThrow(()->MetadataActivity.value("NUMBER",raw));for(String raw:List.of("1e56","0.0000000000000000001","123456789012345678901234567890123456789","NaN","\"1\"","1 2","{}","null"))assertThrows(IllegalArgumentException.class,()->MetadataActivity.value("NUMBER",raw));}
 @Test void stringsRetainFrozenNonNulControlsAndDatesUseTheProlepticCalendar(){assertDoesNotThrow(()->MetadataActivity.value("STRING","\"text\\u0001\\n\""));assertDoesNotThrow(()->MetadataActivity.value("DATE","\"1582-10-10\""));for(var pair:List.of(List.of("STRING","\"\\u0000\""),List.of("DATE","\"2026-02-30\""),List.of("BOOLEAN","1"),List.of("STRING_LIST","[1]"),List.of("STRING_LIST","[\""+"x".repeat(201)+"\"]"),List.of("JSON","{}"),List.of("STRING","\"a\" false")))assertThrows(IllegalArgumentException.class,()->MetadataActivity.value(pair.get(0),pair.get(1)));}
 @Test void retirementPreservesPopulatedAssignmentsAndEmptyClearIsIndependent()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("NOTE_METADATA",id()));var p=NoteMetadataChangedPayloadV1.parseFrom(env.getPayload());var retained=p.toBuilder().setNoteState("RETIRED").addProperties(property("BOOLEAN","false"));var e=ActivityEvent.decode(TOPIC,env.toBuilder().setPayload(retained.build().toByteString()).build().toByteArray());assertEquals("RETIRED",e.state());assertEquals(1,e.metadata().properties().size());assertEquals(List.of(),ActivityEvent.decode(TOPIC,env.toByteArray()).metadata().tags());}
 @Test void duplicateDefinitionsInvalidEnvelopeVersionsAndOversizedSetsAreRejected()throws Exception{var env=RoadmapEventEnvelopeV1.parseFrom(wire("NOTE_METADATA",id()));var p=NoteMetadataChangedPayloadV1.parseFrom(env.getPayload());var tag=MetadataTagV1.newBuilder().setTagId(id().toString()).setName("A").build();var field=property("STRING","\"text\"");var many=p.toBuilder();for(int i=0;i<33;i++)many.addTags(tag.toBuilder().setTagId(id().toString()).setName("T"+i));for(var bad:List.of(p.toBuilder().setMetadataVersion(0),p.toBuilder().setNoteVersion(0),p.toBuilder().setNoteId(id().toString()),p.toBuilder().setRevisionId("bad"),p.toBuilder().setNoteState("MERGED"),p.toBuilder().addTags(tag).addTags(tag),p.toBuilder().addTags(tag).addTags(tag.toBuilder().setTagId(id().toString())),p.toBuilder().addProperties(field).addProperties(field.toBuilder().setPropertyId(id().toString())),p.toBuilder().addTags(tag.toBuilder().setName(" Nonnormalized ")),many))assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(TOPIC,env.toBuilder().setPayload(bad.build().toByteString()).build().toByteArray()));for(var bad:List.of(env.toBuilder().setAggregateType("Note"),env.toBuilder().setEventType("NoteUpdated"),env.toBuilder().setProducer("knowledge-service")))assertThrows(IllegalArgumentException.class,()->ActivityEvent.decode(TOPIC,bad.build().toByteArray()));}
 @Test void legacyRowsAndOtherCursorScopesRemainIndependent(){var json=tools.jackson.databind.json.JsonMapper.builder().build();var e=ActivityEvent.decode(ActivityEvent.TOPICS.get("NOTE_CONCEPTS"),wire("NOTE_CONCEPTS",id()));var tree=(tools.jackson.databind.node.ObjectNode)json.valueToTree(e);tree.remove("metadata");assertEquals(e,json.treeToValue(tree,ActivityEvent.class));var space=id();var row=ActivityEvent.decode(TOPIC,wire("NOTE_METADATA",space));var q=ActivityQuery.parse(space,ActivityQueryTest.params("kind","NOTE_METADATA","timezone","UTC"));var params=ActivityQueryTest.params("kind","NOTE_METADATA","timezone","UTC","before",q.cursor(row));assertEquals(row.eventId(),ActivityQuery.parse(space,params).event());params.put("kind",new String[]{"NOTE"});assertThrows(RuntimeException.class,()->ActivityQuery.parse(space,params));}
}
